function quickModal(){
 const root=document.getElementById('modalRoot');root.className='modal-root show';root.innerHTML='<div class="overlay" data-close><div class="dialog quick-dialog"><h2>Quick Capture</h2><div class="dialog-sub">Ano idadagdag? (task, note, link, habit)</div><input id="quickInput" autocomplete="off" placeholder="task: Bayaran PLDT bukas 5pm"><div class="quick-help"><span>task:</span><span>note:</span><span>link:</span><span>habit:</span></div><div class="capture-list">'+S.captures.slice(-5).reverse().map(c=>'<div class="capture-item">'+esc(c.text)+'<small>'+esc(c.kind)+' · '+c.date+'</small></div>').join('')+'</div><div class="actions"><button class="btn alt" data-cancel>Close</button><button class="btn" id="quickSave">Capture</button></div></div></div>';root.querySelector('[data-cancel]').onclick=closeModal;root.querySelector('.overlay').onclick=e=>{if(e.target===e.currentTarget)closeModal()};const input=document.getElementById('quickInput');input.focus();const submit=()=>{let text=input.value.trim();if(!text)return;capture(text);closeModal();render()};document.getElementById('quickSave').onclick=submit;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();submit()}if(e.key==='Escape')closeModal()}}
function capture(text){
 let lower=text.toLowerCase(),kind='smart';if(lower.startsWith('task:')){kind='task';S.tasks.unshift({id:uid(),title:text.slice(5).trim(),date:TODAY,priority:'mid',category:'General',project:'',done:false,recurring:'none'})}else if(lower.startsWith('note:')){kind='note';S.notes.unshift({id:uid(),type:'Notes',title:'Quick Note',content:text.slice(5).trim(),tags:['quick'],pinned:false,date:TODAY})}else if(lower.startsWith('link:')){kind='link';S.notes.unshift({id:uid(),type:'Links',title:'Saved Link',content:text.slice(5).trim(),tags:['link'],pinned:false,date:TODAY})}else if(lower.startsWith('habit:')){kind='habit';S.habits.unshift({id:uid(),title:text.slice(6).trim(),icon:'✨',checks:{}})}else if(lower.includes('http://')||lower.includes('https://')){kind='link';S.notes.unshift({id:uid(),type:'Links',title:'Saved Link',content:text,tags:['link'],pinned:false,date:TODAY})}else{kind='task';S.tasks.unshift({id:uid(),title:text,date:TODAY,priority:'mid',category:'General',project:'',done:false,recurring:'none'})}S.captures.push({id:uid(),text,kind,date:TODAY});S.captures=S.captures.slice(-30);save()
}
function bind(){
 document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{let t=S.tasks.find(x=>x.id==b.dataset.task);if(!t)return;t.done=b.checked;if(t.done&&t.recurring!=='none')repeatTask(t);save();render()});
 document.querySelectorAll('[data-paid]').forEach(b=>b.onclick=()=>{let c=S.clients.find(x=>x.id==b.dataset.paid);if(c){c.status='Paid';c.history.push({date:TODAY,event:'Marked paid'});save();render()}});
 document.querySelectorAll('[data-remind]').forEach(b=>b.onclick=()=>{let c=S.clients.find(x=>x.id==b.dataset.remind);if(c)navigator.clipboard?.writeText('Hi '+c.name+', gentle reminder lang po sa '+c.project+' invoice na '+money(c.amount,c.currency)+' due '+fmt(c.due)+'. Salamat!');alert('Reminder text copied.');});
 document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{let c=S.clients.find(x=>x.id==b.dataset.history);alert(c.name+' history:\n'+c.history.map(h=>h.date+' — '+h.event).join('\n'))});
 document.getElementById('clientSearch')?.addEventListener('input',()=>{let r=document.getElementById('clientRows');if(r)r.innerHTML=clientRows();bind()});
 document.getElementById('clientStatus')?.addEventListener('change',()=>{let r=document.getElementById('clientRows');if(r)r.innerHTML=clientRows();bind()});
}
function repeatTask(t){let d=new Date(t.date+'T00:00:00');if(t.recurring==='daily')d.setDate(d.getDate()+1);if(t.recurring==='weekly')d.setDate(d.getDate()+7);if(t.recurring==='monthly'){let n=d.getDate();d.setMonth(d.getMonth()+1);if(d.getDate()!==n)d.setDate(0)}S.tasks.push({...t,id:uid(),date:iso(d),done:false})}
function action(a){
 if(a==='quick')quickModal();else if(a==='closing')closingModal();else if(a==='addTask')taskModal();else if(a==='addEvent')eventModal();else if(a==='addClient')clientModal();else if(a==='addNote')noteModal();else if(a==='settings')settingsModal();else if(a==='export')exportData();else if(a==='import')document.getElementById('importInput').click();else if(a==='finance')financeModal();else if(a==='addBudget')budgetModal();else if(a==='addInstallment')installmentModal();else if(a==='addGoal')goalModal();else if(a==='addHabit')habitModal();else if(a==='addLibrary')libraryModal();else if(a==='addBirthday')birthdayModal();else if(a==='addProject')projectModal();else if(a==='addRenewal')renewalModal()
}
