 document.getElementById('app').innerHTML='<div class="onboard"><div class="dialog"><div class="eyebrow">TUBAL HUB v2 · PERSONAL OS</div><h1>Welcome, Ar-ar Tubal 👋</h1><p class="muted">Set up once. Everything stays in your browser unless ikaw ang mag-export.</p><form id="setupForm" class="form"><div class="form-grid"><div class="field"><label>Name</label><input name="name" placeholder="Ar-ar Tubal" required></div><div class="field"><label>City</label><select name="city"><option>Davao City</option><option>Quezon City</option></select></div><div class="field"><label>Currency</label><select name="currency"><option>PHP</option><option>USD</option><option>EUR</option></select></div></div><div class="field"><label>Enable features</label><div class="feature-checks"><label class="feature-check"><input type="checkbox" name="prayer" checked> 🕌 Prayer Conflict Guard</label><label class="feature-check"><input type="checkbox" name="budget" checked> 📊 Budget Forecast</label><label class="feature-check"><input type="checkbox" name="quick" checked> ⚡ Quick Capture</label><label class="feature-check"><input type="checkbox" name="crm" checked> 🧾 Client & Invoice CRM</label><label class="feature-check"><input type="checkbox" name="closing" checked> 🌙 Daily Closing Ritual</label></div></div><button class="btn">Start TUBAL HUB v2 →</button></form></div></div>';
 document.getElementById('setupForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);S.profile={...S.profile,name:f.get('name'),city:f.get('city'),currency:f.get('currency'),setup:true,prayerGuard:f.get('prayer')==='on'};S.settings.prayerGuard=f.get('prayer')==='on';S.settings.closingEnabled=f.get('closing')==='on';save();go('home')}
